var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(EditorApplication.isPlaying||scene.path!="Assets/Scenes/CM_CounterWorkflow07_Review.unity")throw new System.Exception("Production02 Edit mode required");
var dir="ArtSource/Blender/Interiors/CrookedMortar/CounterWorkflow07/";var asset="Assets/BlightBloom/Art/Interiors/CrookedMortar/CounterWorkflow07/";var old=Newtonsoft.Json.Linq.JArray.Parse(System.IO.File.ReadAllText("ArtSource/Blender/Interiors/CrookedMortar/Reconstruction06/ColliderBaseline.json"));var changes=new System.Collections.Generic.List<string>();foreach(var row in old){GlobalObjectId id;GlobalObjectId.TryParse((string)row["id"],out id);var c=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Collider>(true)).FirstOrDefault(c0=>GlobalObjectId.GetGlobalObjectIdSlow(c0).targetObjectId==id.targetObjectId);if(c==null||EditorJsonUtility.ToJson(c)!=(string)row["json"]||c.transform.localToWorldMatrix.ToString()!=(string)row["matrix"]||c.gameObject.activeInHierarchy!=(bool)row["active"])changes.Add((string)row["id"]);}
var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var missingScripts=all.Where(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)>0).Select(t=>t.name).ToArray();var materialMissing=all.Select(t=>t.GetComponent<Renderer>()).Where(r=>r!=null&&r.enabled&&r.gameObject.activeInHierarchy&&r.sharedMaterials.Any(m=>m==null)).Select(r=>r.name).ToArray();
var newModels=AssetDatabase.FindAssets("t:Model",new[]{asset+"Models"}).Select(g=>AssetDatabase.GUIDToAssetPath(g)).SelectMany(p=>AssetDatabase.LoadAllAssetsAtPath(p).OfType<Mesh>()).Select(m=>new{m.name,m.vertexCount,triangles=m.triangles.Length/3,uvs=m.uv.Length,normals=m.normals.Length}).ToArray();
