var report=new{newModels,totalTriangles=newModels.Sum(m=>m.triangles),originalColliders=old.Count,colliderChanges=changes,missingScripts,missingMaterials=materialMissing,newColliderCount=all.Count(t=>t.GetComponent<Collider>()!=null)-old.Count,sweepPoses=43,sweepNewArtHits=hits,doorAngles="180 closed / 75 open: 105 degree outward swing",newPrefabs=AssetDatabase.FindAssets("t:Prefab",new[]{asset+"Prefabs"}).Length};System.IO.File.WriteAllText(dir+"IntegrationValidation.json",Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented));return report;
